SELECT id, customer_id, opened_date, MAX(balance) OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_balance, AVG(balance) OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_balance, MIN(balance) OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_balance, COUNT(balance) OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_count_balance, SUM(balance) OVER (PARTITION BY customer_id ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_balance FROM accounts WHERE opened_date < '2024-01-01';
